  "name": "quality-react-projects",
  "private": true,
  "type": "module",
  "scripts": {
    "start": "node server.mjs",
    "test": "tsx --test tests/*.test.ts",
    "typecheck": "tsc --noEmit",
    "build": "vite build"
  },
  "dependencies": {
    "react": "18.2.0",
    "react-dom": "18.2.0"
  },
  "devDependencies": {
    "@types/react": "18.2.21",
    "@types/react-dom": "18.0.9",
    "typescript": "5.6.3",
    "vite": "5.4.21",
    "tsx": "4.20.6"
  }
}

import {createServer} from 'node:http';
import {createServer as createViteServer} from 'vite';
import {fileURLToPath} from 'node:url';
const vite=await createViteServer({root:fileURLToPath(new URL('.',import.meta.url)),server:{middlewareMode:true,hmr:false},appType:'spa'});
const rows=[{id:'tide',name:'Tide',status:'active'},{id:'forest',name:'Forest',status:'archived'},{id:'north',name:'North',status:'active'}];
let fail=false;const server=createServer(async(req,res)=>{const url=new URL(req.url,'http://127.0.0.1');if(url.pathname==='/__fixture__/mode'&&req.method==='PUT'){let text='';for await(const chunk of req)text+=chunk;try{fail=JSON.parse(text).fail===true;res.end('{}')}catch{res.writeHead(400).end()}return;}if(url.pathname==='/api/projects'){const status=url.searchParams.get('status')||'all';if(!['all','active','archived','paused'].includes(status)){res.writeHead(400).end();return;}await new Promise(resolve=>setTimeout(resolve,status==='active'?600:25));res.setHeader('Content-Type','application/json');if(fail){res.writeHead(503).end('{"error":"fixture failure"}');return;}res.end(JSON.stringify(status==='all'?rows:rows.filter(row=>row.status===status)));return;}vite.middlewares(req,res);});
server.listen(Number(process.env.PORT||0),'127.0.0.1',()=>console.log(`http://127.0.0.1:${server.address().port}/`));
process.on('SIGINT',()=>{server.close();vite.close();});

import {useState} from 'react';
import {useProjects} from './useProjects';
import {ProblemPanel, ProjectRows, SelectedPanel, StatusField} from './ui';
import type {Project, Status} from './types';

export default function App() {
 const [status, setStatus] = useState<Status>('all');
 const [selected, setSelected] = useState<Project | null>(null);
 const {rows, loading, error, retry} = useProjects(status);

 return <>
  <header><h1>Projects</h1><p>Browse projects and keep one selected while filtering.</p></header>
  <main className="layout">
   <section className="panel" aria-label="Project list" aria-busy={loading}>
    <div className="filter">
     <StatusField value={status} onChange={setStatus}/>
     {!loading && !error && <span aria-live="polite">{rows.length} {rows.length === 1 ? 'project' : 'projects'}</span>}
    </div>
    {loading ? <p role="status">Loading projects…</p> : error ? <ProblemPanel message={error} retry={retry}/> : rows.length === 0 ? <p role="status">No projects found</p> : <ProjectRows rows={rows} selectedId={selected?.id ?? null} onSelect={setSelected}/>}
   </section>
   <SelectedPanel project={selected}/>
  </main>
 </>;
}

import type {Project, Status} from './types';
export async function projects(status: Status = 'all', base = ''): Promise<Project[]> {
 const response = await fetch(`${base}/api/projects?status=${encodeURIComponent(status)}`);
 if (!response.ok) throw new Error('Could not load projects');
 return response.json();
}

import {createRoot} from 'react-dom/client';
import App from './App';
import './theme.css';
createRoot(document.getElementById('root')!).render(<App/>);

:root{--accent:#2457c5;--surface:#fff;--line:#d8dee9;--space:24px;color:#182230;font:16px system-ui;background:#f6f7fa}body{margin:32px}header{margin-bottom:var(--space)}.layout{display:grid;grid-template-columns:2fr 1fr;gap:var(--space)}.panel{background:var(--surface);padding:var(--space);border:1px solid var(--line);border-radius:12px}.filter{display:flex;align-items:center;justify-content:space-between;margin-bottom:var(--space)}button,select{font:inherit;padding:10px;border-radius:6px}button{display:block;margin:12px 0;border:1px solid var(--line);background:var(--surface);width:100%;text-align:left;cursor:pointer}.picked{border:2px solid var(--accent)}:focus-visible{outline:3px solid var(--accent);outline-offset:3px}.problem{color:#8b1c1c;border:1px solid #b43b3b;padding:12px}@media(max-width:700px){.layout{grid-template-columns:1fr}body{margin:16px}}

