:root { --user-note-token: 7px; }

import type {Project, Status} from './types';
const options: Status[] = ['all','active','archived','paused'];
export function StatusField({value,onChange}:{value:Status;onChange:(value:Status)=>void}) {return <label>Status <select value={value} onChange={event=>onChange(event.target.value as Status)}>{options.map(option=><option key={option} value={option}>{option[0].toUpperCase()+option.slice(1)}</option>)}</select></label>;}
export function ProjectRows({rows,selectedId,onSelect}:{rows:Project[];selectedId:string|null;onSelect:(project:Project)=>void}) {return <div className="rows">{rows.map(project=><button type="button" key={project.id} data-project-id={project.id} aria-pressed={selectedId===project.id} className={selectedId===project.id?'picked':''} onClick={()=>onSelect(project)}>{project.name} — {project.status[0].toUpperCase()+project.status.slice(1)}</button>)}</div>;}
export function ProblemPanel({message,retry}:{message:string;retry:()=>void}) {return <div role="alert" className="problem">{message}<button type="button" onClick={retry}>Retry</button></div>;}
export function SelectedPanel({project}:{project:Project|null}) {return <aside className="panel"><h2>Selected project</h2><p>{project?.name??'No project selected'}</p></aside>;}

import {useEffect, useState} from 'react';
import {projects} from './api';
import type {Project, Status} from './types';
export function useProjects(status: Status = 'all') {
 const [rows,setRows]=useState<Project[]>([]), [error,setError]=useState<string|null>(null), [loading,setLoading]=useState(true), [reload,setReload]=useState(0);
 const [request, setRequest] = useState({status, reload});
 // Hide the previous query's result immediately, before the new effect starts.
 const pending = request.status !== status || request.reload !== reload;
 useEffect(()=>{let current=true;setRequest({status,reload});setLoading(true);setError(null);projects(status).then(value=>{if(current)setRows(value)}).catch(reason=>{if(current)setError(String(reason.message))}).finally(()=>{if(current)setLoading(false)});return ()=>{current=false}},[status,reload]);
 return {rows,error:pending ? null : error,loading:pending || loading,retry:()=>setReload(value=>value+1)};
}

import {test} from 'node:test';
import assert from 'node:assert/strict';
import {spawn} from 'node:child_process';
import {once} from 'node:events';
import {fileURLToPath} from 'node:url';
import {projects} from '../src/api.ts';

test('API owner uses all real server filters and distinguishes failure from empty success', async () => {
 const server = spawn(process.execPath, ['server.mjs'], {
  cwd: fileURLToPath(new URL('..', import.meta.url)),
  env: {...process.env, PORT: '0'},
  stdio: ['ignore', 'pipe', 'pipe'],
 });
 let errors = '';
 server.stderr.on('data', chunk => { errors += chunk; });
 try {
  const base = await new Promise<string>((resolve, reject) => {
   const timeout = setTimeout(() => reject(new Error(`Server startup timed out: ${errors}`)), 10000);
   server.once('error', error => { clearTimeout(timeout); reject(error); });
   server.once('exit', code => { clearTimeout(timeout); reject(new Error(`Server exited ${code}: ${errors}`)); });
   server.stdout.on('data', chunk => {
    const url = String(chunk).match(/http:\/\/127\.0\.0\.1:\d+/)?.[0];
    if (url) { clearTimeout(timeout); resolve(url); }
   });
  });
  const all = await projects('all', base);
  assert.deepEqual(all.map(row => row.id), ['tide', 'forest', 'north']);
  assert.deepEqual(await projects('active', base), all.filter(row => row.status === 'active'));
  assert.deepEqual(await projects('archived', base), all.filter(row => row.status === 'archived'));
  assert.deepEqual(await projects('paused', base), []);
  assert.equal((await fetch(`${base}/__fixture__/mode`, {method: 'PUT', body: JSON.stringify({fail: true})})).ok, true);
  await assert.rejects(projects('archived', base), /Could not load projects/);
  assert.equal((await fetch(`${base}/__fixture__/mode`, {method: 'PUT', body: JSON.stringify({fail: false})})).ok, true);
  assert.deepEqual(await projects('archived', base), [all[1]]);
 } finally {
  const exited = once(server, 'exit');
  server.kill('SIGINT');
  await exited;
 }
});

